// Why: A # field can only be read inside the class: `account.balance` from outside is
// undefined. Validate before changing state so a failed call leaves it untouched.
// Docs: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Using_classes
// Test driver: don't change. Runs each [method, ...args] and records the result.
function run(actions) {
  const account = new BankAccount("Ada");
  return actions.map(([method, ...args]) => {
    if (method === "publicBalance") return account.balance;
    try {
      return account[method](...args);
    } catch (error) {
      return `${error.name}: ${error.message}`;
    }
  });
}

class BankAccount {
  #balance = 0;

  constructor(owner) {
    this.owner = owner;
  }

  deposit(amount) {
    if (amount <= 0) throw new RangeError("deposit must be positive");
    this.#balance += amount;
    return this.#balance;
  }

  withdraw(amount) {
    if (amount > this.#balance) throw new RangeError("insufficient funds");
    this.#balance -= amount;
    return this.#balance;
  }

  getBalance() {
    return this.#balance;
  }
}

