// Why: A subclass must call super() before it uses `this`. It inherits describe() and
// overrides area(), so Shape's describe() calls the right area for each shape.
// Docs: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Classes/extends
// Test driver: don't change.
function check(specs) {
  return specs.map(([kind, ...dims]) => {
    const shape = kind === "circle" ? new Circle(...dims) : new Rectangle(...dims);
    return [shape instanceof Shape, shape.describe()];
  });
}

class Shape {
  constructor(name) {
    this.name = name;
  }
  area() {
    return 0;
  }
  describe() {
    return `${this.name} with area ${this.area().toFixed(2)}`;
  }
}

class Circle extends Shape {
  constructor(radius) {
    super("circle");
    this.radius = radius;
  }
  area() {
    return Math.PI * this.radius ** 2;
  }
}

class Rectangle extends Shape {
  constructor(width, height) {
    super("rectangle");
    this.width = width;
    this.height = height;
  }
  area() {
    return this.width * this.height;
  }
}

